import { useState } from 'react';
import useDispatchStore from '../../state/dispatchStore.js';
import { useSignalingContext } from '../../context/SignalingContext.jsx';
import PageModal from '../PageModal/index.jsx';

function StatusDot({ status, isEmergency }) {
  const isOffline = status === 'offline';
  const color = isEmergency 
    ? 'bg-red-500' 
    : isOffline
      ? 'bg-gray-500'
      : status === 'transmitting' 
        ? 'bg-yellow-500' 
        : 'bg-green-500';
  
  return (
    <span
      className={`inline-block w-2 h-2 rounded-full ${color} ${isEmergency ? 'animate-pulse' : ''} ${isOffline ? 'opacity-50' : ''}`}
      title={isOffline ? 'Offline' : undefined}
    />
  );
}

function formatTime(timestamp) {
  if (!timestamp) return '';
  const date = new Date(timestamp);
  return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });
}

function LocationIcon({ tracking }) {
  return (
    <svg
      className={`w-3.5 h-3.5 ${tracking ? 'text-green-400 animate-pulse' : 'text-dispatch-secondary'}`}
      fill="none"
      stroke="currentColor"
      viewBox="0 0 24 24"
    >
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
    </svg>
  );
}

export default function UnitList() {
  const { units } = useDispatchStore();
  const { trackedUnits, emitTrackStart, emitTrackStop } = useSignalingContext();
  const [pageTarget, setPageTarget] = useState(null);

  const handleToggleTracking = (unitIdentity) => {
    if (trackedUnits.includes(unitIdentity)) {
      emitTrackStop(unitIdentity);
    } else {
      emitTrackStart(unitIdentity);
    }
  };

  return (
    <div className="flex flex-col h-full">
      <div className="flex items-center justify-between mb-3">
        <h2 className="text-sm font-bold text-dispatch-text uppercase tracking-wide">Units</h2>
        <span className="text-xs text-dispatch-secondary">{units.length} total</span>
      </div>

      {pageTarget && (
        <PageModal
          target={pageTarget}
          onClose={() => setPageTarget(null)}
        />
      )}

      <div className="flex-1 overflow-y-auto space-y-1 scrollbar-thin">
        {units.length === 0 ? (
          <div className="text-xs text-dispatch-secondary text-center py-4">
            No units found
          </div>
        ) : (
          units.map(unit => {
            const isOffline = unit.status === 'offline';
            const isTracking = trackedUnits.includes(unit.unit_identity);
            return (
              <div
                key={unit.id}
                className={`unit-card p-2.5 rounded-md text-sm transition-all ${
                  unit.is_emergency 
                    ? 'unit-card-emergency' 
                    : ''
                }`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <StatusDot status={unit.status} isEmergency={unit.is_emergency} />
                    <span className={`font-medium ${isOffline ? 'text-dispatch-secondary' : 'text-dispatch-text'}`}>
                      {unit.unit_identity}
                    </span>
                    {isTracking && <LocationIcon tracking={true} />}
                  </div>
                  <span className="text-xs text-dispatch-tertiary font-mono">{formatTime(unit.last_seen)}</span>
                </div>
                <div className="flex items-center justify-between mt-1.5">
                  <span className="text-xs text-dispatch-secondary">{unit.channel || 'Unknown'}</span>
                  <div className="flex items-center gap-1.5">
                    <button
                      onClick={() => handleToggleTracking(unit.unit_identity)}
                      className={`text-xs px-1.5 py-0.5 rounded transition-colors flex items-center gap-1 ${
                        isTracking 
                          ? 'bg-green-600/30 text-green-400 hover:bg-green-600/50' 
                          : 'bg-dispatch-border text-dispatch-secondary hover:text-dispatch-text'
                      }`}
                      title={isTracking ? 'Stop Tracking' : 'Track Location'}
                    >
                      <LocationIcon tracking={isTracking} />
                      {isTracking ? 'Stop' : 'Track'}
                    </button>
                    <button
                      onClick={() => setPageTarget({ type: 'unit', id: unit.unit_identity, label: unit.unit_identity })}
                      className="text-xs px-1.5 py-0.5 rounded transition-colors bg-amber-600 text-white hover:bg-amber-500"
                      title="Send Page"
                    >
                      PAGE
                    </button>
                    <span className="text-xs px-1.5 py-0.5 rounded bg-dispatch-border text-dispatch-secondary">
                      {(() => {
                        const s = (unit.status || '').toUpperCase();
                        if (!s || s === 'ONDT' || s === 'ON DUTY' || s === 'ONLINE') return 'ONDT';
                        return s;
                      })()}
                    </span>
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}
